<?php
/** Isolated delivery state-machine fixture; never uses application DB configuration. */
declare(strict_types=1);
$inCi=getenv('GITHUB_ACTIONS')==='true' && getenv('CI')==='true';
$local=getenv('COREFLUX_DELIVERY_LOCAL_FIXTURE')==='1' && in_array('--confirm-disposable-fixture',$argv,true) && (string)getenv('COREFLUX_DELIVERY_TEST_PASSWORD')!=='';
if(!$inCi&&!$local)throw new RuntimeException('Explicit disposable fixture configuration required');
putenv('COREFLUX_DATA_KEY='.base64_encode(random_bytes(32)));
putenv('COREFLUX_DISABLE_DATABASE=1');
require_once __DIR__.'/../core/integrations/delivery.php';
require_once __DIR__.'/../core/quanta/workspace.php';
require_once __DIR__.'/../core/migrate.php';
$pdo=new PDO('mysql:host=127.0.0.1;port=3306;charset=utf8mb4','root',$inCi?'root':getenv('COREFLUX_DELIVERY_TEST_PASSWORD'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
$db='coreflux_delivery_'.($inCi?'ci':gmdate('YmdHis').'_'.getmypid());
$pdo->exec('CREATE DATABASE '.$db);$pdo->exec('USE '.$db);
foreach(coreflux_split_sql_statements(file_get_contents(__DIR__.'/../core/migrations/158_integration_deliveries.sql'))as$sql)$pdo->exec($sql);
$passed=0;
$check=static function(bool $ok,string $label)use(&$passed):void{if(!$ok)throw new RuntimeException($label);$passed++;echo "PASS {$label}\n";};
$fails=static function(callable $f):bool{try{$f();return false;}catch(Throwable $e){return true;}};
$hash=static fn(string $s):string=>hash('sha256',$s);
$ctx=['provider'=>'quanta','connection_ref'=>'1','binding_hash'=>$hash('binding'),'entity_type'=>'person','entity_tenant_id'=>2,'entity_id'=>42,'operation'=>'worker.create','source_hash'=>$hash('source'),'remote_hash'=>$hash('remote')];
$payload=['fields'=>['full_name'=>'Synthetic Worker','email'=>'synthetic@example.test']];
$fresh=array_intersect_key($ctx,array_flip(['binding_hash','source_hash','remote_hash']));
$new=static fn(array $c):array=>integrationDeliveryPreview($pdo,1,7,$c,$payload);
$a=$new($ctx);$id=(int)$a['id'];
$check($a['state']==='preview','preview never sends');
$check(!str_contains($a['payload_ct'],'Synthetic Worker'),'payload encrypted at rest');
$check(json_decode(decryptField($a['payload_ct']),true)===integrationDeliveryCanonical($payload),'encrypted payload round trips');
$check($new($ctx)['id']===$a['id'],'identical preview reuses envelope');
$check($new($ctx)['idempotency_key']===$a['idempotency_key'],'replay preserves idempotency key');
$check($fails(fn()=>integrationDeliveryGet($pdo,9,$id)),'foreign tenant read blocked');
$check(!array_intersect(['payload_ct','binding_hash','claim_hash','idempotency_key'],array_keys(integrationDeliverySummary($a))),'API summary excludes sensitive internals');
$check($fails(fn()=>integrationDeliveryClaim($pdo,1,$id,$fresh)),'unreviewed delivery cannot be claimed');
$check($fails(fn()=>integrationDeliveryApprove($pdo,1,$id,7,$hash('wrong'))),'wrong preview revision rejected');
integrationDeliveryApprove($pdo,1,$id,7,$a['review_hash']);
$check($fails(fn()=>integrationDeliveryApprove($pdo,1,$id,7,$a['review_hash'])),'repeat approval cannot reset delivery');
$pdo->beginTransaction();
$check($fails(fn()=>integrationDeliveryClaim($pdo,1,$id,$fresh)),'uncommitted outer transaction cannot send');$pdo->rollBack();
$claim=integrationDeliveryClaim($pdo,1,$id,$fresh);
$check($claim['payload']===integrationDeliveryCanonical($payload) && !$pdo->inTransaction(),'claim is committed before provider IO');
$check($fails(fn()=>integrationDeliveryClaim($pdo,1,$id,$fresh)),'second claim cannot duplicate attempt');
$check($fails(fn()=>integrationDeliveryFinish($pdo,1,$id,$hash('wrong'),'delivered','remote-1')),'foreign claim cannot finish');
$check($fails(fn()=>integrationDeliveryFinish($pdo,9,$id,$claim['claim'],'delivered','remote-1')),'foreign tenant cannot finish');
$check($fails(fn()=>integrationDeliveryFinish($pdo,1,$id,$claim['claim'],'delivered')),'success requires confirmed remote identity');
integrationDeliveryFinish($pdo,1,$id,$claim['claim'],'uncertain',null,'network_timeout');
$check($fails(fn()=>integrationDeliveryClaim($pdo,1,$id,$fresh)),'timeout is not automatically retried');
$b=$new(array_replace($ctx,['source_hash'=>$hash('new-source')]));
integrationDeliveryApprove($pdo,1,(int)$b['id'],7,$b['review_hash']);
$check($fails(fn()=>integrationDeliveryClaim($pdo,1,(int)$b['id'],array_replace($fresh,['source_hash'=>$hash('new-source')]))),'changed payload cannot bypass an uncertain attempt');
$check($fails(fn()=>integrationDeliveryCancel($pdo,1,$id)),'uncertain attempt cannot be discarded as cancelled');
$c=$new(array_replace($ctx,['entity_id'=>43]));$cid=(int)$c['id'];
integrationDeliveryApprove($pdo,1,$cid,7,$c['review_hash']);
$check($fails(fn()=>integrationDeliveryClaim($pdo,1,$cid,array_replace($fresh,['binding_hash'=>$hash('other-workspace')]))),'reconnected workspace invalidates review');
$check(integrationDeliveryGet($pdo,1,$cid)['state']==='conflict','stale binding enters conflict state');
foreach(['source_hash'=>46,'remote_hash'=>47]as$revision=>$entity){
    $stale=$new(array_replace($ctx,['entity_id'=>$entity]));
    integrationDeliveryApprove($pdo,1,(int)$stale['id'],7,$stale['review_hash']);
    $check($fails(fn()=>integrationDeliveryClaim($pdo,1,(int)$stale['id'],array_replace($fresh,[$revision=>$hash('changed')]))),$revision.' drift prevents provider attempt');
    $check(integrationDeliveryGet($pdo,1,(int)$stale['id'])['attempted_at']===null,$revision.' conflict never marks a provider attempt');
}
$d=$new(array_replace($ctx,['entity_id'=>44]));$did=(int)$d['id'];
$pdo->exec('UPDATE integration_deliveries SET expires_at=DATE_SUB(NOW(),INTERVAL 1 SECOND) WHERE id='.$did);
$check($fails(fn()=>integrationDeliveryApprove($pdo,1,$did,7,$d['review_hash'])),'expired review refused');
$d=$new(array_replace($ctx,['entity_id'=>44]));
integrationDeliveryApprove($pdo,1,$did,7,$d['review_hash']);
$dc=integrationDeliveryClaim($pdo,1,$did,$fresh);
integrationDeliveryFinish($pdo,1,$did,$dc['claim'],'delivered','worker-confirmed');
$check(integrationDeliveryGet($pdo,1,$did)['state']==='delivered','repreview renews only an unattempted expiry');
$check($new(array_replace($ctx,['entity_id'=>44]))['state']==='delivered','terminal delivery replay remains delivered');
$again=$new(array_replace($ctx,['entity_id'=>44,'source_hash'=>$hash('second-create')]));
integrationDeliveryApprove($pdo,1,(int)$again['id'],7,$again['review_hash']);
$check($fails(fn()=>integrationDeliveryClaim($pdo,1,(int)$again['id'],array_replace($fresh,['source_hash'=>$hash('second-create')]))),'source change cannot create a previously delivered worker again');
$check($fails(fn()=>integrationDeliveryFinish($pdo,1,$did,$dc['claim'],'failed',null,'duplicate')),'late callback cannot change terminal result');
$e=$new(array_replace($ctx,['entity_id'=>45]));
integrationDeliveryCancel($pdo,1,(int)$e['id']);
$check($fails(fn()=>integrationDeliveryApprove($pdo,1,(int)$e['id'],7,$e['review_hash'])),'cancelled review cannot be approved');
$check($fails(fn()=>$new(array_replace($ctx,['entity_tenant_id'=>0]))),'missing directory owner rejected');
$check($fails(fn()=>$new(array_replace($ctx,['provider'=>'unverified-provider']))),'unknown provider rejected');
$check($fails(fn()=>$new(array_replace($ctx,['provider'=>'purepayroll','operation'=>'payroll.execute']))),'unimplemented financial execution cannot enter queue');
$other=integrationDeliveryPreview($pdo,2,8,$ctx,$payload);
$check($other['id']!==$a['id'],'same external IDs stay isolated between tenants');
// Verify organization binding with real transactions and connection changes.
$pdo->exec('CREATE TABLE quanta_connections (id BIGINT PRIMARY KEY,tenant_id BIGINT NOT NULL UNIQUE,status VARCHAR(20),api_key_ct VARBINARY(2048)) ENGINE=InnoDB');
foreach(coreflux_split_sql_statements(file_get_contents(__DIR__.'/../core/migrations/159_quanta_workspace_binding.sql'))as$sql)$pdo->exec($sql);
$key='synthetic-workspace-key';$rotated='rotated-workspace-key';
$insert=$pdo->prepare('INSERT INTO quanta_connections (id,tenant_id,status,api_key_ct) VALUES (?,?,"active",?)');
$insert->execute([1,1,encryptField($key)]);$insert->execute([2,2,encryptField($key)]);
$instance='381e452a-5d11-4e2e-9daa-e9427501898a';
$context=['workspace'=>['id'=>'synthetic-a','name'=>'Synthetic A'],'contract_version'=>QUANTA_CORE_CONTRACT_VERSION,
    'capabilities'=>['person_links','assignment_metadata','conditional_assignment_updates','durable_delivery_receipts'],'execution_side_effects'=>false];
$bindingHash=quantaWorkspaceBindingHash(1,1,$key,$instance,$context);
$check($fails(fn()=>quantaWorkspaceBind($pdo,1,7,['id'=>1],$key,$instance,$context,str_repeat('0',64))),'changed confirmation snapshot cannot bind');
$check(quantaWorkspaceBindingGet($pdo,1)===null,'failed confirmation leaves no binding');
$binding=quantaWorkspaceBind($pdo,1,7,['id'=>1],$key,$instance,$context,$bindingHash);
$check(quantaWorkspaceBindingMatches($binding,$bindingHash),'reviewed workspace binding commits independently');
$check(quantaWorkspaceBindingGet($pdo,2)===null,'organization binding is isolated by Core tenant');
$foreign=array_replace($context,['workspace'=>['id'=>'synthetic-b','name'=>'Synthetic A']]);
$foreignHash=quantaWorkspaceBindingHash(1,1,$key,$instance,$foreign);
$check($fails(fn()=>quantaWorkspaceBind($pdo,1,7,['id'=>1],$key,$instance,$foreign,$foreignHash)),'same display name cannot retarget established remote identities');
$check(quantaWorkspaceBindingGet($pdo,1)['remote_workspace_id']==='synthetic-a','failed retarget rolls back');
$check($fails(fn()=>quantaWorkspaceBind($pdo,2,7,['id'=>1],$key,$instance,$context,quantaWorkspaceBindingHash(2,1,$key,$instance,$context))),'connection from another tenant cannot bind');
$pdo->prepare('UPDATE quanta_connections SET api_key_ct=? WHERE tenant_id=1')->execute([encryptField('unexpected-key')]);
$check($fails(fn()=>quantaWorkspaceBind($pdo,1,7,['id'=>1],$key,$instance,$context,$bindingHash)),'credential drift is caught even if another writer did not advance the revision');
$pdo->prepare('UPDATE quanta_connections SET api_key_ct=? WHERE tenant_id=1')->execute([encryptField($key)]);
$pdo->beginTransaction();
$check($fails(fn()=>quantaWorkspaceBind($pdo,1,7,['id'=>1],$key,$instance,$context,$bindingHash)),'caller transaction cannot roll back an acknowledged binding');$pdo->rollBack();
quantaWorkspaceReconfigure($pdo,1,static function()use($pdo,$rotated):void{$pdo->prepare('UPDATE quanta_connections SET api_key_ct=? WHERE tenant_id=1')->execute([encryptField($rotated)]);});
$check(!quantaWorkspaceBindingMatches(quantaWorkspaceBindingGet($pdo,1),$bindingHash),'key rotation revokes previous verification atomically');
$check($fails(fn()=>quantaWorkspaceBind($pdo,1,7,['id'=>1],$key,$instance,$context,$bindingHash)),'key changed during review is rejected under connection lock');
$rotatedHash=quantaWorkspaceBindingHash(1,1,$rotated,$instance,$context,2);
$binding=quantaWorkspaceBind($pdo,1,7,['id'=>1,'binding_revision'=>2],$rotated,$instance,$context,$rotatedHash);
$check(quantaWorkspaceBindingMatches($binding,$rotatedHash),'same workspace can be explicitly reverified after rotation');
$check($fails(fn()=>quantaWorkspaceReconfigure($pdo,1,static function()use($pdo):void{$pdo->exec('UPDATE quanta_connections SET status="revoked" WHERE tenant_id=1');throw new RuntimeException('fixture failure');})),'failed reconfiguration propagates failure');
$check($pdo->query('SELECT status FROM quanta_connections WHERE tenant_id=1')->fetchColumn()==='active' && quantaWorkspaceBindingMatches(quantaWorkspaceBindingGet($pdo,1),$rotatedHash),'failed reconfiguration rolls back connection and verification together');
quantaWorkspaceReconfigure($pdo,1,static function()use($pdo):void{$pdo->exec('UPDATE quanta_connections SET status="revoked",api_key_ct=NULL WHERE tenant_id=1');});
$check(quantaWorkspaceBindingGet($pdo,1)['state']==='revoked','disconnect retains historical identity and revokes verification');
$check($fails(fn()=>quantaWorkspaceBind($pdo,1,7,['id'=>1,'binding_revision'=>3],$rotated,$instance,$context,quantaWorkspaceBindingHash(1,1,$rotated,$instance,$context,3))),'disconnected connection cannot be verified');
quantaWorkspaceReconfigure($pdo,1,static function()use($pdo,$rotated):void{$pdo->prepare('UPDATE quanta_connections SET status="active",api_key_ct=? WHERE tenant_id=1')->execute([encryptField($rotated)]);});
$check($fails(fn()=>quantaWorkspaceBind($pdo,1,7,['id'=>1,'binding_revision'=>2],$rotated,$instance,$context,$rotatedHash)),'disconnect and reconnect with the identical key cannot replay old confirmation');
$check((int)$pdo->query('SELECT binding_revision FROM quanta_connections WHERE tenant_id=1')->fetchColumn()===4,'each successful connection change advances its revision; failures do not');
foreach(coreflux_split_sql_statements(file_get_contents(__DIR__.'/../core/migrations/159_quanta_workspace_binding.sql'))as$sql)$pdo->exec($sql);
$check((int)$pdo->query('SELECT binding_revision FROM quanta_connections WHERE tenant_id=1')->fetchColumn()===4,'migration replay preserves connection revision');
echo "Integration deliveries MariaDB: {$passed} passed\n";
